BIN={ast.Add:operator.add,ast.Sub:operator.sub,ast.Mult:operator.mul,ast.Div:operator.truediv,ast.Mod:operator.mod,ast.Pow:operator.pow,
     ast.Eq:operator.eq,ast.NotEq:operator.ne,ast.Lt:operator.lt,ast.LtE:operator.le,ast.Gt:operator.gt,ast.GtE:operator.ge,
     ast.In:lambda a,b:a in b,ast.NotIn:lambda a,b:a not in b}
UN={ast.Not:operator.not_,ast.USub:operator.neg,ast.UAdd:operator.pos}
def _eval(n, env):
    if isinstance(n,ast.Expression): return _eval(n.body,env)
    if isinstance(n,ast.Constant): return n.value
    if isinstance(n,ast.Name): return env.get(n.id,'')
    if isinstance(n,ast.Subscript): return env.get(n.value.id,'')[n.slice.value]
    if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):
        name=n.func.id;args=[_eval(x,env) for x in n.args]
        funcs={'lower':lambda x:str(x).lower(),'upper':lambda x:str(x).upper(),'trim':lambda x:str(x).strip(),'len':len,
               'contains':lambda x,y:y in x,'startswith':lambda x,y:str(x).startswith(str(y)),
               'endswith':lambda x,y:str(x).endswith(str(y)),'int':lambda x:int(float(x)),'float':float,
               'abs':abs,'round':round,'col':lambda x:env['_'][int(x)] if isinstance(x,(int,float)) else env.get(str(x),'')}
        if name not in funcs:raise ValueError('unknown function: '+name)
        return funcs[name](*args)
    if isinstance(n,ast.List): return [_eval(x,env) for x in n.elts]
    if isinstance(n,ast.BoolOp):
        if isinstance(n.op,ast.And):
            for x in n.values:
                if not _eval(x,env):return False
            return True
        for x in n.values:
            if _eval(x,env):return True
        return False
    if isinstance(n,ast.UnaryOp): return UN[type(n.op)](_eval(n.operand,env))
    if isinstance(n,ast.BinOp):
        a,b=_eval(n.left,env),_eval(n.right,env)
        if isinstance(n.op,ast.MatMult):return str(a)+str(b)
        if type(n.op) in (ast.Add,ast.Sub,ast.Mult,ast.Div,ast.Mod,ast.Pow):
            try:a=float(a);b=float(b)
            except (ValueError,TypeError):
                if isinstance(n.op,ast.Add):return str(a)+str(b)
                raise
        return BIN[type(n.op)](a,b)
    if isinstance(n,ast.Compare):
        left=_eval(n.left,env)
        for op,rightnode in zip(n.ops,n.comparators):
            right=_eval(rightnode,env)
            if isinstance(left,(int,float)) or isinstance(right,(int,float)):
                try:l,r=float(left),float(right)
                except (ValueError,TypeError):
                    symbol={ast.Eq:'==',ast.NotEq:'!=',ast.Lt:'<',ast.LtE:'<=',ast.Gt:'>',ast.GtE:'>='}.get(type(op),str(type(op)))
                    bad=left if not isinstance(left,(int,float)) else right
                    raise ValueError(f'{symbol} cannot safely cast Bytes("{bad}") from type "bytes" to type "number"')
            elif type(op) in (ast.Lt,ast.LtE,ast.Gt,ast.GtE):
                try:l,r=float(left),float(right)
                except (ValueError,TypeError):
                    symbol={ast.Lt:'<',ast.LtE:'<=',ast.Gt:'>',ast.GtE:'>='}[type(op)]
                    bad=left if isinstance(left,str) else right
                    raise ValueError(f'{symbol} cannot safely cast Bytes("{bad}") from type "bytes" to type "number"')
            else:l,r=left,right
            if not BIN[type(op)](l,r):return False
            left=right
        return True
    raise ValueError('unsupported expression')

def run(args):
    p=argparse.ArgumentParser(prog='xan filter')
    p.add_argument('-f','--evaluate-file',action='store_true');p.add_argument('-v','--invert-match',action='store_true')
    p.add_argument('-l','--limit',type=int);p.add_argument('-n','--no-headers',action='store_true');p.add_argument('-d','--delimiter',default=',');p.add_argument('-o','--output')
    p.add_argument('expression');p.add_argument('input',nargs='?');ns=p.parse_args(args)
    expr=open(ns.expression,encoding='utf-8').read() if ns.evaluate_file else ns.expression
    expr=expr.replace('&&',' and ').replace('||',' or ')
    # Moonblade uses a single equals sign for equality.
    import re
    expr=re.sub(r'\btrue\b','True',expr,flags=re.I);expr=re.sub(r'\bfalse\b','False',expr,flags=re.I)
    expr=re.sub(r'\bnull\b','None',expr,flags=re.I)
    for a,b in [('eq','=='),('ne','!='),('lt','<'),('le','<='),('gt','>'),('ge','>=')]:expr=re.sub(r'\b'+a+r'\b',b,expr)
    expr=expr.replace('++','@')
    tree=ast.parse(expr,mode='eval')
    f=open(ns.input,encoding='utf-8',newline='') if ns.input and ns.input!='-' else sys.stdin
    try: rows=[row for row in csv.reader(f,delimiter=ns.delimiter) if row]
    finally:
        if f is not sys.stdin:f.close()
    if not rows:return
    head=[] if ns.no_headers else rows[0]
    out=open(ns.output,'w',encoding='utf-8',newline='') if ns.output else sys.stdout
    writer=csv.writer(out,delimiter=',',lineterminator='\n')
    if not ns.no_headers:writer.writerow(rows[0])
    data=rows if ns.no_headers else rows[1:]
    matched=0
    if ns.limit is not None and ns.limit <= 0:
        if out is not sys.stdout:out.close()
        return
    for idx,row in enumerate(data):
        env={h:(row[i] if i<len(row) else '') for i,h in enumerate(head)}
        env.update({'_':row,'index':idx})
        try: keep=bool(_eval(tree,env))
        except Exception as e:
            print(f'xan filter: {e}',file=sys.stderr)
            if out is not sys.stdout:out.close()
            raise SystemExit(1)
        if ns.invert_match:keep=not keep
        if keep:
            writer.writerow(row);matched+=1
            if ns.limit is not None and matched>=ns.limit:break
    if out is not sys.stdout:out.close()

